void IupacSynthProcessor::prepareToPlay(double rate,int block){coordinator_.prepare(rate,static_cast<std::size_t>(std::max(1,block)));const auto c=engine::compilePatch(document_.editedPatch);if(c){std::scoped_lock lock(documentMutex_);publishDocument(c.patch);}setLatencySamples(4);}
void IupacSynthProcessor::publishDocument(const engine::CompiledPatch&patch){(void)coordinator_.publish(patch,readControls());if(!coordinator_.retryPending()&&!publishRetry_.isTimerRunning())publishRetry_.startTimer(5);}
void IupacSynthProcessor::PublishRetry::timerCallback(){std::scoped_lock lock(owner.documentMutex_);if(owner.coordinator_.retryPending())stopTimer();}
bool IupacSynthProcessor::isBusesLayoutSupported(const BusesLayout&l)const{return l.getMainOutputChannelSet()==juce::AudioChannelSet::stereo()&&l.getMainInputChannelSet().isDisabled();}
