// Called when an editor opens (#97): the private payload costs 13-30 s the first
// time macOS executes it after an install, and that cost belongs in the background
// while the user is still looking at the synth, never on the message thread and
// never on the first Apply. At most one warm-up runs per processor.
void IupacSynthProcessor::prewarmChemistry(){if(chemistry_)chemistry_->prewarm();}
